#!/usr/bin/env node
// Frozen V1 production artifact guard.
//
// lib/onchain/community-pool-v1-artifact.json is the exact artifact the
// production app deploys every CommunityPool from, and it matches the two
// existing mainnet V1 pools byte-for-byte (see docs/contracts-build.md). It is
// never regenerated by the artifact pipeline. This guard fails if:
//   1. the file is missing,
//   2. its creation-bytecode keccak256 is not the pinned V1 hash, or
//   3. the production deployment helper stops importing it (or starts
//      importing a candidate artifact).
//
// Changing the pinned hash below is an explicit, code-review-visible event
// that means "production now deploys different bytecode".

import { readFileSync, existsSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { keccak256 } from "ethers";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");

export const FROZEN_V1_ARTIFACT_PATH = "lib/onchain/community-pool-v1-artifact.json";
export const FROZEN_V1_CREATION_BYTECODE_KECCAK =
  "0xf564efc7c38adc4016e2e09b431d33797f597d4e0fb174bd818bebafb4060c98";
export const PRODUCTION_DEPLOY_HELPER = "lib/onchain/community-pool.ts";

export function checkFrozenV1Artifact() {
  const problems = [];
  const artifactPath = resolve(root, FROZEN_V1_ARTIFACT_PATH);
  if (!existsSync(artifactPath)) {
    problems.push(`${FROZEN_V1_ARTIFACT_PATH} is missing`);
  } else {
    const artifact = JSON.parse(readFileSync(artifactPath, "utf8"));
    const hash = keccak256(artifact.bytecode);
    if (hash !== FROZEN_V1_CREATION_BYTECODE_KECCAK) {
      problems.push(
        `${FROZEN_V1_ARTIFACT_PATH} creation bytecode keccak is ${hash}, expected ${FROZEN_V1_CREATION_BYTECODE_KECCAK}`,
      );
    }
    const ctor = artifact.abi.find((x) => x.type === "constructor");
    if (!ctor || ctor.inputs.length !== 7) {
      problems.push("V1 constructor must have exactly 7 inputs (no protocolConfig parameter)");
    }
    if (artifact.abi.some((x) => x.type === "function" && x.name === "getProtocolFeeConfig")) {
      problems.push("V1 ABI must not expose getProtocolFeeConfig (that is V2)");
    }
  }
  const helperPath = resolve(root, PRODUCTION_DEPLOY_HELPER);
  const helper = readFileSync(helperPath, "utf8");
  if (!/from\s+["']\.\/community-pool-v1-artifact\.json["']/.test(helper)) {
    problems.push(`${PRODUCTION_DEPLOY_HELPER} must import ./community-pool-v1-artifact.json`);
  }
  // Phase 2.8: new pools deploy V2. The V1 artifact stays for reading/interacting with the
  // existing live pools, but it must never reach a ContractFactory again.
  if (!/COMMUNITY_POOL_V2_ARTIFACT\.bytecode/.test(helper)) {
    problems.push(`${PRODUCTION_DEPLOY_HELPER} must deploy new pools from COMMUNITY_POOL_V2_ARTIFACT`);
  }
  if (/new ContractFactory\(\s*artifact\.abi/.test(helper)) {
    problems.push(`${PRODUCTION_DEPLOY_HELPER} must not deploy the frozen V1 artifact`);
  }
  return problems;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const problems = checkFrozenV1Artifact();
  if (problems.length) {
    console.error("[check-frozen-v1-artifact] FAIL\n  - " + problems.join("\n  - "));
    process.exit(1);
  }
  console.log(
    `[check-frozen-v1-artifact] OK — ${FROZEN_V1_ARTIFACT_PATH} creation bytecode keccak ${FROZEN_V1_CREATION_BYTECODE_KECCAK}; V1 frozen, new pools deploy V2.`,
  );
}
